export function disposeResearch(){if(root)persistSession();drawingStudio?.dispose();drawingStudio=null;formulaStudio?.dispose();formulaStudio=null;formulaOcrPanel?.dispose();formulaOcrPanel=null;researchEpoch++;formulaRender++;jobPanel?.dispose();jobPanel=null;controller?.abort();controller=null;root=null;dirty=false;busy=false;supplementalDirty=false;}
const $=s=>root?.querySelector(s);
export const researchHasWork=()=>!!root?.querySelector('.research-space')&&(dirty||supplementalDirty||busy||drawingStudio?.hasUnsaved());
export function researchRouteGuard(){if(!root?.querySelector('.research-space'))return true;if(busy){ctx.notify('正在读取或导出，请稍候。');return false;}if(!persistSession()){ctx.notify('当前浏览器未能保存草稿，请先导出备份再离开。');return false;}dirty=false;supplementalDirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(root&&!persistSession()&&researchHasWork()){e.preventDefault();e.returnValue='';}});
export function mountResearch(context,id,projectId){disposeResearch();controller=new AbortController();ctx=context;const loaded=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='research');let session={};if(!hasDraftScope()&&!id){try{session=JSON.parse(localStorage.getItem(researchSessionKey)||'{}');}catch{}}chart=loaded?.chart?structuredClone(loaded.chart):!id&&session.chart?session.chart:exampleChart();chart.id=loaded?.chart?loaded.id:chart.id;chart.projectId=loaded?.projectId||projectId||chart.projectId||'';if(loaded&&!loaded.chart&&!loaded.diagram&&!loaded.formula){try{const data=parseTable('类别,数值\n'+loaded.material);Object.assign(chart,data,{title:loaded.title,example:false});}catch{ctx.notify('旧图表材料无法转换，请保留原记录并重新输入数据。');chart.id=undefined;}}dirty=false;busy=false;tab='manual';mode=loaded?.diagram?'structure':loaded?.formula?'formula':loaded?'data':!id&&['basic','pro','formula','stats','data','structure'].includes(session.mode)?session.mode:'basic';formula=loaded?.formula||session.formula||'';formulaId=loaded?.formula?loaded.id:session.formulaId||'';formulaSvg='';diagram=loaded?.diagram||session.diagram||null;diagramId=loaded?.diagram?loaded.id:session.diagramId||'';diagramDraft=loaded?.diagram?{}:session.diagramDraft||{};proDescription=loaded?.requirements||session.proDescription||'';proType=session.proType||'';requirements=loaded?.formula?loaded.requirements||'':session.requirements||'';jobStates=session.jobStates||{};history=Array.isArray(session.history)?session.history.slice(0,12):[];if(!id&&!hasDraftScope()){const queryMode=new URLSearchParams(location.hash.split('?')[1]||'').get('mode'),mappedMode=queryMode==='professional'?'pro':queryMode;if(['basic','pro','formula','stats','data','structure'].includes(mappedMode))mode=mappedMode;}root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});}
function persistSession(){if(drawingStudio&&!drawingStudio.saveDraft()){saveError='浏览器未能自动保存绘图描述，请复制备份后重试。';return false;}if(hasDraftScope()){saveError='';return true;}try{if(jobPanel)jobStates[mode]=jobPanel.getState();localStorage.setItem(researchSessionKey,JSON.stringify({chart,mode,formula,formulaId,diagram,diagramId,diagramDraft,proDescription,proType,requirements,jobStates,history,updatedAt:new Date().toISOString()}));saveError='';return true;}catch{saveError='浏览器未能自动保存，请导出备份。';return false;}}
function rememberVersion(kind,value){history.unshift({id:crypto.randomUUID(),kind,value:structuredClone(value),at:new Date().toISOString()});history=history.slice(0,12);persistSession();}
function aiArea(){return '<div id="research-ai-panel"></div>';}
async function openResearchAI(){if(hasDraftScope()){ctx.notify('当前在编辑账户成果，请先保存到账户，再从科研工具页面发起 AI 处理。手动编辑与导出仍可使用，当前不会提交或扣费。');return;}const epoch=researchEpoch,currentMode=mode,container=$('#research-ai-panel');if(!container)return;if(!jobPanel){const {mountToolJobPanel}=await import('./tool-job-panel.mjs');if(epoch!==researchEpoch||mode!==currentMode||!container.isConnected)return;jobPanel=mountToolJobPanel({container,ctx,kind:'research',operation:['pro','structure'].includes(mode)?'diagram':mode==='formula'?'formula':'chart',initialState:jobStates[mode]||{},isCurrent:()=>epoch===researchEpoch&&mode===currentMode&&container.isConnected,getSnapshot:()=>{if(mode==='data'){validateData(chart);if(!chart.title.trim())throw Error('请先填写图表标题。');return {title:chart.title,text:requirements||'请根据当前真实表格选择适合论文的图表类型、标题、坐标轴与单位，保留全部原始数值。',language:'中文',mode:'chart',context:{table:{headers:chart.headers,rows:chart.rows},example:!!chart.example},materials:[]};}if(['pro','structure'].includes(mode)){if(proDescription.trim().length<8)throw Error('请说明至少 8 字的结构、元素和关系。');return {title:'专业结构示意图',text:proDescription,requirements:'只生成结构示意图，不生成仿真、CAD、医学诊断或未经提供的实验数据。节点标识使用字母、数字、下划线。',language:'中文',mode:proType!==''?proTypes[Number(proType)]:'结构图',materials:[]};}return {title:'科研数学公式',text:formula||requirements,requirements:requirements||'请用标准数学 LaTeX 给出公式，并说明符号含义，不计算未经提供的实验结果。',language:'中文',mode:'formula',materials:[]};},onStateChange:state=>{if(hasDraftScope())throw Error('请先保存当前账户成果，再从科研工具页面确认 AI 处理。当前不会提交或扣费。');jobStates[currentMode]=state;if(!persistSession())throw Error('当前浏览器未能保存任务草稿，已停止提交。请先导出或释放存储空间，避免重复扣费。');},onApply:output=>{if(mode==='data'){const next=applyChartAdvice(chart,output.chart);rememberVersion('chart',chart);chart=next;mark();draw();ctx.notify('已应用图表配置，原始数据保持一致。');}else if(['pro','structure'].includes(mode)){const next=validateDiagram(output.diagram);if(diagram)rememberVersion('diagram',diagram);diagram=next;diagramDraft={};mark();draw();ctx.notify('结构图已生成，请核对并编辑节点关系。');}else{const next=validateFormulaCode(output.latex);if(formula)rememberVersion('formula',formula);formula=next;mark();draw();ctx.notify('公式已填入，请核对符号和适用条件。');}}});}jobPanel.open();}
function renderHistory(){const kind=['pro','structure'].includes(mode)?'diagram':mode==='formula'?'formula':'chart',rows=history.filter(row=>row.kind===kind).slice(0,5);return rows.length?`<details class="research-version-history"><summary>编辑历史 · ${rows.length} 个可恢复版本</summary>${rows.map(row=>`<div><span>${esc(formatDate(row.at))}</span><button class="btn secondary" data-restore-version="${esc(row.id)}">恢复此版本</button></div>`).join('')}</details>`:'';}
async function updateFormula(){const epoch=researchEpoch,renderId=++formulaRender,preview=$('#formula-preview');formulaSvg='';if(!preview)return;if(!formula.trim()){preview.textContent='输入 LaTeX 后在这里排版预览';return;}preview.textContent='正在排版…';try{const latex=validateFormulaCode(formula),{renderFormulaSvg}=await import('./assets/research-formula.js');const svg=renderFormulaSvg(latex);if(epoch!==researchEpoch||renderId!==formulaRender||!preview.isConnected)return;formulaSvg=svg;preview.innerHTML=svg;const error=$('#formula-render-error');if(error)error.textContent='';}catch(error){if(epoch!==researchEpoch||renderId!==formulaRender||!preview.isConnected)return;preview.textContent=formula;const field=$('#formula-render-error');if(field)field.textContent=error.message||'公式排版失败，请检查语法。';}}

function field(key,label,max=60){return `<label>${label}<input data-option="${key}" aria-label="${label}" value="${esc(chart[key])}" maxlength="${max}"></label>`;}
function nav(){return `<nav class="research-tools research-mode-cards" data-scroll-key="research-tools-1" aria-label="科研工具分类">${[['basic','chart','基础图表','描述需求，直接生成论文配图','AI 科研绘图'],['pro','grid','专业绘图','为不同研究领域生成专业示意图','12 个专业领域'],['formula','file','公式编辑','模板、符号、识别与实时排版','公式工作台']].map(([id,glyph,title,description,state],index)=>`<button data-mode="${id}" class="${mode===id||mode==='structure'&&id==='pro'||['data','stats'].includes(mode)&&id==='basic'?'active':''}" aria-pressed="${mode===id||mode==='structure'&&id==='pro'||['data','stats'].includes(mode)&&id==='basic'}"><span class="research-mode-art" aria-hidden="true">${icon(glyph,50)}</span><span class="research-mode-card-top"><span class="research-mode-icon">${icon(glyph,22)}</span><small>${state}</small></span><b>${title}</b><span class="research-mode-description">${description}</span><span class="research-mode-bottom">0${index+1} / ${id==='formula'?'公式与符号':'描述生成图片'}${icon('arrow',15)}</span></button>`).join('')}</nav><div class="research-advanced-links" style="display:flex;gap:16px;justify-content:flex-end;margin:-6px 0 18px;flex-wrap:wrap"><button class="btn secondary" data-mode="data">数据绘图</button><button class="btn secondary" data-mode="structure">结构图编辑</button></div>`;}
